// 7 state components: signup, login, welcome (post-signup modal), forgot, reset, verify, recover.

type AuthIconName =
  | "check"
  | "arrow"
  | "back"
  | "close"
  | "eye"
  | "eye-off"
  | "mail"
  | "lock"
  | "gift"
  | "note"
  | "image"
  | "alert"
  | "clock"
