                  </button>
                ) : (
                  <button type="submit" className="auth-submit" disabled={submitting}>
                    {submitting ? "Logging in..." : "Log In"} <AuthIcon name="arrow" w={16} />
                  </button>
                )}

                <div className="auth-cardfoot">
                  Don't have an account?{' '}
                  <Link href="/signup">Sign up →</Link>
                </div>
              </form>
            </section>
        </div>
      </div>
    </div>
  );
}

