              />
              <p className="bmc-help">Typography and colors are chosen automatically to suit the generated image</p>
            </div>
          </div>
        </div>
      </div>

      <BmcFoot costLabel={<CreditCost n={1} />} onBack={onBack} onNext={tryContinue} />
    </>
  );
}

